import os
from amazon import AmazonTextract

def normalize_expense(payload, config=None):
    config = config or {}
    client = AmazonTextract.Client(
        region_name=config.get('region_name', 'us-east-1'),
        aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY')
    )

    response = client.detect_document_text(Document={'Bytes': payload})

    # Extract fields using heuristics based on Amazon Textract response structure
    expense_data = {
        "total_amount": None,
        "date": None,
        "merchant": None,
        "category": None
    }

    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            text = item['Text'].strip()
            if 'total' in text.lower() or 'amount' in text.lower():
                # Heuristic: look for currency patterns
                import re
                match = re.search(r'\$?\d+\.\d{2}', text)
                if match:
                    expense_data["total_amount"] = float(match.group().replace('$', ''))
            elif 'date' in text.lower():
                # Heuristic: look for date patterns
                match = re.search(r'\d{2}/\d{2}/\d{4}', text)
                if match:
                    expense_data["date"] = match.group()
            elif 'merchant' in text.lower() or 'store' in text.lower():
                expense_data["merchant"] = text.split(':')[-1].strip() if ':' in text else text
            elif 'category' in text.lower():
                expense_data["category"] = text.split(':')[-1].strip() if ':' in text else text

    result = expense_data
    return result
